INSERT INTO housing_notice_unit (
    notice_id, house_sn, hsmp_nm, brtc_nm, signgu_nm, full_adres,
    heat_mthd_nm, tot_hshld_co, sum_suply_co, rent_gtn, mt_rntchrg, enty, surlus
)
SELECT
    notice.id, unit_data.house_sn, unit_data.hsmp_nm, unit_data.brtc_nm,
    unit_data.signgu_nm, unit_data.full_adres, unit_data.heat_mthd_nm,
    unit_data.tot_hshld_co, unit_data.sum_suply_co, unit_data.rent_gtn,
    unit_data.mt_rntchrg, unit_data.enty, unit_data.surlus
FROM unit_data
JOIN housing_notice notice ON notice.pblanc_id = unit_data.pblanc_id;

